from sympy import Symbol, Poly

# Decode the one-dimensional piecewise-affine decision regions from weight
# coefficients. No inputs, network layers, or output heads are evaluated.
a = W["target.w0"][:, 0].astype(float)
b = W["target.b0"].astype(float)
out = W["target.w1"].astype(float)
bias = W["target.b1"].astype(float)

def decision_regions(scale, head):
    knots = sorted(set([0.0, 10.000001] + [
        float(-b[i] / (scale * a[i]))
        for i in range(len(a))
        if a[i] > 0 and 0 < -b[i] / (scale * a[i]) < 10.000001
    ]))
    regions = {j: [] for j in range(3)}
    for left, right in zip(knots, knots[1:]):
        # Active hinges are determined algebraically by their roots.
        active = np.array([
            a[i] > 0 and -b[i] / (scale * a[i]) <= left + 1e-10
            or a[i] == 0 and b[i] > 0
            for i in range(len(a))
        ])
        slopes = out[3*head:3*head+3, active] @ (scale * a[active])
        intercepts = bias[3*head:3*head+3] + out[3*head:3*head+3, active] @ b[active]
        for j in range(3):
            lo, hi = left, right
            for k in range(3):
                if k == j:
                    continue
                m = slopes[j] - slopes[k]
                c = intercepts[j] - intercepts[k]
                if abs(m) < 1e-12:
                    if c < 0:
                        lo, hi = 1, 0
                        break
                elif m > 0:
                    lo = max(lo, -c/m)
                else:
                    hi = min(hi, -c/m)
            if lo <= hi:
                regions[j].append((lo, hi))
    return regions

