import json
import numpy as np
import sympy as sp

u = W["target.w0"][:, 0].astype(float)
v = W["target.b0"].astype(float)
c = W["target.w1"].astype(float)
d = W["target.b1"].astype(float)

# A scalar spline is represented by its knot locations and changes in
# affine coefficients; class regions follow from linear inequalities.
knots = -v / (0.67 * u)
order = np.argsort(knots)
bounds = sorted({0.0, 10.00001} |
                {float(t) for t in knots if 0.0 < t < 10.00001})

def class_intervals(head):
    results = [[] for _ in range(3)]
    for left, right in zip(bounds[:-1], bounds[1:]):
        selected = order[knots[order] <= left + 1e-10]
        coeff = c[3*head:3*head+3, selected]
        slope = coeff @ (0.67*u[selected])
        const = d[3*head:3*head+3] + coeff @ v[selected]
        for j in range(3):
            low, high = left, right
            for k in range(3):
                if j == k:
                    continue
                delta = slope[j] - slope[k]
                offset = const[j] - const[k]
                if abs(delta) < 1e-12:
                    if offset < 0:
                        low, high = 1.0, 0.0
                        break
                elif delta > 0:
                    low = max(low, -offset/delta)
                else:
                    high = min(high, -offset/delta)
            if low <= high:
                results[j].append((low, high))
    return results

def class_map(intervals):
    mapping = {}
    for label, ranges in enumerate(intervals):
        for lo, hi in ranges:
            for n in range(11):
                if lo - 1e-8 <= n <= hi + 1e-8:
                    mapping.setdefault(n, label)
    assert len(mapping) == 11
    return mapping

x = sp.Symbol("x")
generating = sum((1+x+x*x)**n for n in range(1, 6)).expand()
multiplicity = [int(generating.coeff(x, n)) for n in range(11)]
original = [
    {n: int(n >= 3) + int(n >= 7) for n in range(11)},
    {n: n % 3 for n in range(11)}
]
scaled = [class_map(class_intervals(h)) for h in range(2)]
zero = {n: 0 for n in range(11)}

def fraction(h, mapping):
    return sum(multiplicity[n] for n in range(11)
               if mapping[n] != original[h][n]) / 363

